'use strict';
(function(){
 const ball=$('bookmark-ball'),panel=$('bookmark-panel'),search=$('bookmark-search'),list=$('bookmark-list'),chat=$('chat'),dialog=$('bookmark-dialog'),name=$('bookmark-name');
 let pending=null,items=[],automaticCache=[],selected=0,drag=null;
 const active=()=>!chat.hidden&&activeView===state.active;
 const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
 function position(){if(!active())return;const width=chat.clientWidth,height=chat.clientHeight,pos=state.bookmarkBall||{x:1,y:.18},maxX=Math.max(0,width-ball.offsetWidth),maxY=Math.max(0,height-ball.offsetHeight);ball.style.left=(clamp(pos.x,0,1)*maxX)+'px';ball.style.top=(clamp(pos.y,0,1)*maxY)+'px';placePanel();}
 function placePanel(){if(panel.hidden)return;const bw=ball.offsetWidth,pw=panel.offsetWidth,ph=panel.offsetHeight,x=ball.offsetLeft,y=ball.offsetTop;panel.style.left=clamp(x-pw-8,6,Math.max(6,chat.clientWidth-pw-6))+'px';if(x-pw-8<6)panel.style.left=clamp(x+bw+8,6,Math.max(6,chat.clientWidth-pw-6))+'px';panel.style.top=clamp(y,6,Math.max(6,chat.clientHeight-ph-6))+'px';}
 function defaults(){const result=[],order=new Map(current().turns.map((t,i)=>[t.id,i]));for(const answer of $('thread').querySelectorAll('.answer')){const turn=order.get(answer.dataset.turn);if(turn===undefined)continue;for(const passage of answer.querySelectorAll(':scope>.passage')){const h=passage.querySelector('h1,h2,h3,h4,h5,h6');if(h){const marker=h.querySelector('.heading-marker')?.textContent||'['+(turn+1)+':h'+h.tagName.slice(1)+']';result.push({kind:'default',name:marker.replace(/[\[\]]/g,''),description:h.querySelector('.heading-label')?.textContent||'',turn:answer.dataset.turn,block:passage.id});}for(const eq of passage.querySelectorAll('.equation[id]')){const n=eq.querySelector('.equation-number')?.textContent.replace(/\D/g,'');if(n)result.push({kind:'default',name:(turn+1)+':eq'+n,description:eq.querySelector('.math')?.dataset.tex||'',turn:answer.dataset.turn,block:passage.id,target:eq.id});}}}return result;}
 function byDocument(a,b){const left=$(a.block),right=$(b.block);if(left&&right&&left!==right){const relation=left.compareDocumentPosition(right);if(relation&Node.DOCUMENT_POSITION_FOLLOWING)return -1;if(relation&Node.DOCUMENT_POSITION_PRECEDING)return 1;}const turns=current().turns,li=turns.findIndex(t=>t.id===a.turn),ri=turns.findIndex(t=>t.id===b.turn);return li-ri||(a.offset||0)-(b.offset||0);}
 function refresh(){const q=search.value.trim().toLocaleLowerCase(),numeric=/^\d/.test(q),matches=x=>!q||(numeric?x.name.toLocaleLowerCase().startsWith(q):(x.name+' '+(x.description||'')).toLocaleLowerCase().includes(q));const automatic=automaticCache.filter(matches),users=(current().bookmarks||[]).map(b=>({...b,kind:'user'})).sort(current().bookmarkSort==='dictionary'?(a,b)=>a.name.localeCompare(b.name,'zh-CN')||byDocument(a,b):byDocument).filter(matches);items=[...automatic,...users];selected=clamp(selected,0,Math.max(0,items.length-1));const row=(b,i)=>'<div class="bookmark-row"><button type="button" class="bookmark-target" data-bookmark="'+i+'" aria-selected="'+(selected===i)+'" title="'+esc(b.description||b.name)+'">'+esc(b.name)+(b.description?' · '+esc(b.description):'')+'</button>'+(b.kind==='user'?'<button class="bookmark-remove" type="button" data-remove-bookmark="'+esc(b.id)+'" aria-label="删除标签 '+esc(b.name)+'">×</button>':'')+'</div>';list.innerHTML='<div class="bookmark-section-head"><span>默认书签</span></div>'+(automatic.map(row).join('')||'<div class="bookmark-empty">没有匹配的标题或公式</div>')+'<div class="bookmark-section-head"><span>用户标签</span><select id="bookmark-sort" aria-label="用户标签排序"><option value="document">行文顺序</option><option value="dictionary">字典顺序</option></select></div>'+(users.map((b,i)=>row(b,i+automatic.length)).join('')||'<div class="bookmark-empty">没有匹配的标签</div>');$('bookmark-sort').value=current().bookmarkSort||'document';placePanel();}
 function open(focus){if(!active())return;panel.hidden=false;ball.setAttribute('aria-expanded','true');selected=0;automaticCache=defaults();refresh();if(focus){search.focus();search.select();}}
 function close(){panel.hidden=true;ball.setAttribute('aria-expanded','false');}
 function destination(item){const turn=current().turns.find(t=>t.id===item.turn);if(!turn)return status('书签所在轮次已不存在。');const old=$(item.block),answer=old?.closest('.answer')||$(item.endBlock)?.closest('.answer');turn.collapsed=false;if(answer&&old){let stack=[];for(const p of answer.querySelectorAll(':scope>.passage')){const h=p.querySelector('h1,h2,h3,h4,h5,h6');if(h){const level=Number(h.tagName.slice(1));stack=stack.filter(x=>x.level<level);stack.push({level,id:p.id});}if(p===old||p.id===item.endBlock){for(const h of stack)if(turn.sections)turn.sections[h.id]=false;}}}renderTurns();close();requestAnimationFrame(()=>{const anchor=$(item.target)||readingAnchor(item.block);if(!anchor){status('书签所在内容已不存在。');return;}anchor.scrollIntoView({block:'center'});const target=item.scope==='answer'?anchor.closest('.answer'):item.scope==='turn'?$(item.turn):anchor;if(item.kind==='user'&&item.quote&&target){const walker=document.createTreeWalker(target,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())if(!walker.currentNode.parentElement.closest('.margin-notes,svg'))nodes.push(walker.currentNode);const text=nodes.map(n=>n.textContent).join(''),at=text.startsWith(item.quote,item.offset||0)?(item.offset||0):text.indexOf(item.quote,Math.max(0,(item.offset||0)-4));if(at>=0){let start=at,end=at+item.quote.length,base=0,range=document.createRange(),started=false;for(const n of nodes){const len=n.length;if(!started&&start<=base+len){range.setStart(n,Math.max(0,start-base));started=true;}if(started&&end<=base+len){range.setEnd(n,Math.max(0,end-base));const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);const rect=range.getBoundingClientRect(),reader=$('reader').getBoundingClientRect();if(rect.height&&rect.top>=reader.top-2000&&rect.bottom<=reader.bottom+2000)$('reader').scrollTop+=rect.top-reader.top-reader.height/2;break;}base+=len;}}else status('标签原文已变化，已定位到所在段落。');}saveReading();});}
 function currentSelection(event){const selection=window.getSelection();if(!selection||selection.isCollapsed||!selection.rangeCount)return null;const range=selection.getRangeAt(0),start=range.startContainer.nodeType===1?range.startContainer:range.startContainer.parentElement,end=range.endContainer.nodeType===1?range.endContainer:range.endContainer.parentElement,turn=start.closest('.turn');if(!turn||turn!==end.closest('.turn'))return null;const block=start.closest('.passage,.question')||turn,endBlock=end.closest('.passage,.question')||turn,answer=start.closest('.answer'),scope=block.contains(range.endContainer)?'block':answer&&answer===end.closest('.answer')?'answer':'turn',root=scope==='answer'?answer:scope==='turn'?turn:block;const prefix=range.cloneRange(),raw=selection.toString();prefix.selectNodeContents(root);prefix.setEnd(range.startContainer,range.startOffset);return {turn:turn.id,block:block.id,endBlock:endBlock.id,scope,quote:raw.trim(),offset:prefix.toString().length+raw.length-raw.trimStart().length};}
 function unavailable(){const selection=window.getSelection();if(!running?.turn||!selection?.rangeCount||selection.isCollapsed)return '';const range=selection.getRangeAt(0),turn=$(running.turn.id);if(!turn)return '';if([...turn.querySelectorAll('.streaming-answer,.answer')].some(node=>range.intersectsNode(node)))return '回答生成结束后可添加标签。';const question=turn.querySelector('.question');if(question&&range.intersectsNode(question)){if((running.turn.annotations||[]).length)return '带圈点的实时提问请在本轮结束后添加标签。';try{const saved=JSON.parse(localStorage.getItem(KEY)||'null'),conversation=saved?.conversations?.find(c=>c.id===current().id),stored=conversation?.turns?.find(t=>t.id===running.turn.id);if(!stored)return '提问正在保存，请稍后添加标签。';if((stored.prompt??stored.question)!==(running.turn.prompt??running.turn.question))return '当前实时提问在本轮结束后可添加标签。';}catch{return '提问正在保存，请稍后添加标签。';}}return '';}
 $('thread').addEventListener('contextmenu',event=>{const reason=unavailable(),quote=window.getSelection()?.toString().trim(),inside=event.target.closest('.turn');pending=reason?null:currentSelection(event);const button=$('bookmark-selection'),note=$('bookmark-unavailable');button.disabled=!pending?.quote;note.hidden=!reason;note.textContent=reason;if(!event.target.closest('.answer')&&inside&&quote){event.preventDefault();context={quote,selected:true};closePopups();const menu=$('answer-menu');menu.hidden=false;menu.style.left=Math.min(event.clientX,innerWidth-menu.offsetWidth-6)+'px';menu.style.top=Math.min(event.clientY,innerHeight-menu.offsetHeight-6)+'px';$('annotate').disabled=true;$('copy-selection').disabled=false;$('copy-answer').disabled=true;}else{$('annotate').disabled=false;$('copy-answer').disabled=false;}});
 $('bookmark-selection').onclick=()=>{if(!pending?.quote)return;closePopups();name.value=[...pending.quote.replace(/\s+/g,' ')].slice(0,120).join('');dialog.showModal();name.focus();name.select();};
 $('bookmark-cancel').onclick=()=>dialog.close();$('bookmark-form').onsubmit=event=>{event.preventDefault();const label=name.value.trim();if(!label||!pending)return;current().bookmarks||=[];current().bookmarks.push({...pending,id:crypto.randomUUID(),name:label});persist();dialog.close();pending=null;};
 ball.addEventListener('pointerdown',event=>{if(event.button!==0)return;drag={id:event.pointerId,x:event.clientX,y:event.clientY,left:ball.offsetLeft,top:ball.offsetTop,moved:false};ball.setPointerCapture(event.pointerId);});
 ball.addEventListener('pointermove',event=>{if(!drag||drag.id!==event.pointerId)return;const dx=event.clientX-drag.x,dy=event.clientY-drag.y;if(Math.hypot(dx,dy)>3)drag.moved=true;if(!drag.moved)return;const maxX=Math.max(0,chat.clientWidth-ball.offsetWidth),maxY=Math.max(0,chat.clientHeight-ball.offsetHeight);state.bookmarkBall={x:maxX?clamp(drag.left+dx,0,maxX)/maxX:0,y:maxY?clamp(drag.top+dy,0,maxY)/maxY:0};position();});
 ball.addEventListener('pointerup',event=>{if(!drag||drag.id!==event.pointerId)return;const moved=drag.moved;drag=null;if(moved)persist();else if(panel.hidden)open(true);else close();});ball.addEventListener('pointercancel',()=>{drag=null;});ball.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();if(panel.hidden)open(true);else close();}});
 search.addEventListener('input',()=>{selected=0;refresh();});search.addEventListener('keydown',event=>{if(event.isComposing)return;if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();if(items.length){selected=(selected+(event.key==='ArrowDown'?1:-1)+items.length)%items.length;list.querySelectorAll('[data-bookmark]').forEach((node,i)=>node.setAttribute('aria-selected',String(i===selected)));list.querySelector('[aria-selected=true]')?.scrollIntoView({block:'nearest'});}}else if(event.key==='Enter'){event.preventDefault();if(items[selected])destination(items[selected]);}});
 list.addEventListener('click',event=>{const target=event.target.closest('[data-bookmark]'),remove=event.target.closest('[data-remove-bookmark]');if(target){const item=items[Number(target.dataset.bookmark)];if(item)destination(item);}else if(remove){current().bookmarks=(current().bookmarks||[]).filter(b=>b.id!==remove.dataset.removeBookmark);persist();refresh();}});list.addEventListener('change',event=>{if(event.target.id==='bookmark-sort'){current().bookmarkSort=event.target.value;persist();refresh();}});
 document.addEventListener('keydown',event=>{if(event.ctrlKey&&!event.altKey&&!event.shiftKey&&event.key.toLowerCase()==='g'&&active()){event.preventDefault();event.stopPropagation();open(true);}else if(event.key==='Escape'&&!panel.hidden){event.preventDefault();event.stopPropagation();close();ball.focus();}},true);
 document.addEventListener('pointerdown',event=>{if(!panel.hidden&&!event.target.closest('#bookmark-ball,#bookmark-panel'))close();});window.addEventListener('resize',position);new ResizeObserver(position).observe(chat);position();
})();
